#!/usr/bin/env python3
"""Bundle secondary-table editor/diagnostic metadata from the shared ABI model."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tools'))
from secondary_config import DEFAULT,ENUMS,LABELS,ENUM_FIELDS,SCALARS,VALUE_NAMES,VALUE_LABELS,BOOLEAN_FIELDS,REASONS,INPUT_SOURCES,AXIS_UNITS,CONDITION_UNITS,CELL_UNITS
metadata=dict(defaults=DEFAULT,enums=ENUMS,labels=LABELS,enumFields=ENUM_FIELDS,scalars=SCALARS,values=VALUE_NAMES,valueLabels=VALUE_LABELS,boolFields=BOOLEAN_FIELDS,reasons=REASONS,inputSources=INPUT_SOURCES,axisUnits=AXIS_UNITS,conditionUnits=CONDITION_UNITS,cellUnits=CELL_UNITS)
(ROOT/'web/secondary_tables.js').write_text('// Generated by scripts/generate_secondary_ui.py\nwindow.EcuSecondaryMetadata='+json.dumps(metadata,separators=(',',':'))+';\n'+(ROOT/'web/secondary_tables_logic.js').read_text())
